/// Columns whose bit is set in `mask` (bit c = column c, c < 64). At least column 0 when none is set.
fn projection(buf: *[64]usize, width: usize, mask: u64) []const usize {
    var n: usize = 0;
    for (0..@min(width, 64)) |c| {
        const shift: u6 = @truncate(c); // c < 64
        if (((mask >> shift) & 1) == 1) {
            buf[n] = c;
            n += 1;
        }
    }
    if (n == 0 and width > 0) {
        buf[0] = 0;
        n = 1;
    }
    return buf[0..n];
}

